begin;
create table if not exists hq.hr_contracts (id uuid primary key default gen_random_uuid(), employee_id uuid not null references hq.employees(id) on delete cascade, contract_type text not null, starts_on date not null, ends_on date, status text not null default 'draft' check(status in ('draft','active','expired','terminated')), document_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists hq.hr_documents (id uuid primary key default gen_random_uuid(), employee_id uuid not null references hq.employees(id) on delete cascade, document_type text not null, storage_path text not null, expires_on date, created_at timestamptz not null default now());
create table if not exists hq.hr_attendance (id uuid primary key default gen_random_uuid(), employee_id uuid not null references hq.employees(id) on delete cascade, work_date date not null, shift_code text, checked_in_at timestamptz, checked_out_at timestamptz, status text not null check(status in ('present','absent','late','excused')), minutes_late integer not null default 0, unique(employee_id,work_date));
create table if not exists hq.hr_leave_requests (id uuid primary key default gen_random_uuid(), employee_id uuid not null references hq.employees(id) on delete cascade, leave_type text not null, starts_on date not null, ends_on date not null, status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')), approved_by uuid references hq.employees(id), created_at timestamptz not null default now());
create table if not exists hq.hr_payroll_records (id uuid primary key default gen_random_uuid(), employee_id uuid not null references hq.employees(id) on delete cascade, period_start date not null, period_end date not null, gross_amount numeric(14,2) not null default 0, deductions numeric(14,2) not null default 0, net_amount numeric(14,2) generated always as (gross_amount-deductions) stored, currency char(3) not null default 'MZN', status text not null default 'draft' check(status in ('draft','approved','paid','void')), created_at timestamptz not null default now(), unique(employee_id,period_start,period_end));
create table if not exists hq.hr_employee_events (id uuid primary key default gen_random_uuid(), employee_id uuid not null references hq.employees(id) on delete cascade, event_type text not null check(event_type in ('admission','benefit','performance_review','training','disciplinary','promotion','transfer','separation')), title text not null, occurred_on date not null default current_date, status text not null default 'open', metadata jsonb not null default '{}'::jsonb, created_by uuid references hq.employees(id), created_at timestamptz not null default now());
alter table hq.hr_contracts enable row level security; alter table hq.hr_documents enable row level security; alter table hq.hr_attendance enable row level security; alter table hq.hr_leave_requests enable row level security; alter table hq.hr_payroll_records enable row level security; alter table hq.hr_employee_events enable row level security;
revoke all on hq.hr_contracts,hq.hr_documents,hq.hr_attendance,hq.hr_leave_requests,hq.hr_payroll_records,hq.hr_employee_events from public,anon,authenticated;
grant all on hq.hr_contracts,hq.hr_documents,hq.hr_attendance,hq.hr_leave_requests,hq.hr_payroll_records,hq.hr_employee_events to service_role;
create index if not exists idx_hr_attendance_date on hq.hr_attendance(work_date desc,status); create index if not exists idx_hr_leave_status on hq.hr_leave_requests(status,starts_on); create index if not exists idx_hr_events_employee on hq.hr_employee_events(employee_id,occurred_on desc);
commit;
